'use strict';
document.documentElement.classList.add('js');
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}},{threshold:.08});
document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));
const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('nav');
menu?.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');menu.textContent=open?'×':'☰'});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav?.classList.contains('open')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='☰';menu.focus()}});
// Gallery: supplied business photographs only; no fabricated additional images.
const photo=document.querySelector('#gallery-photo');
if(photo){let index=0,timer,paused=reduced.matches;const images=['assets/treatment-1.webp','assets/treatment-2.webp','assets/treatment-3.webp'];const pause=document.querySelector('#gallery-pause');const render=()=>{photo.src=images[index];photo.alt=`Madero Slim supplied body treatment photo ${index+1}`;document.querySelector('#gallery-count').textContent=`0${index+1} / 03`};const next=delta=>{index=(index+delta+images.length)%images.length;render()};const sync=()=>{clearInterval(timer);pause.textContent=paused?'▷':'Ⅱ';pause.setAttribute('aria-label',paused?'Play slideshow':'Pause slideshow');if(!paused&&!document.hidden)timer=setInterval(()=>next(1),5500)};document.querySelector('#gallery-prev').onclick=()=>{next(-1);sync()};document.querySelector('#gallery-next').onclick=()=>{next(1);sync()};pause.onclick=()=>{paused=!paused;sync()};document.addEventListener('visibilitychange',sync);reduced.addEventListener('change',e=>{paused=e.matches;sync()});sync()}
const ask=document.querySelector('#ask-booking');
ask?.addEventListener('click',()=>{const treatment=document.querySelector('#treatment').value,area=document.querySelector('#area').value;const text=`Hello Madero Slim! I’m interested in ${treatment} for a home session in ${area}. Please confirm availability, suitability and the final price.`;window.open('https://wa.me/971521275611?text='+encodeURIComponent(text),'_blank','noopener')});
// A dependency-free 3D parametric sculpture, projected and lit in canvas.
// Mesh geometry, depth sorting and normals provide actual perspective and lighting.
const canvas=document.querySelector('#sculpture');
if(canvas){const ctx=canvas.getContext('2d');let width=0,height=0,turn=0,paused=reduced.matches,visible=true,raf=0,last=0;const toggle=document.querySelector('#motion-toggle');let pointerX=0,pointerY=0;
const normal=(a,b,c)=>{const u=b.map((v,i)=>v-a[i]),v=c.map((x,i)=>x-a[i]);const n=[u[1]*v[2]-u[2]*v[1],u[2]*v[0]-u[0]*v[2],u[0]*v[1]-u[1]*v[0]];const l=Math.hypot(...n)||1;return n.map(x=>x/l)};
const point=(u,v)=>{const ring=1.08+.15*Math.sin(u*3+.6),tube=.36+.07*Math.sin(u*2);return [(ring+tube*Math.cos(v))*Math.cos(u),1.24*(ring+tube*Math.cos(v))*Math.sin(u),tube*Math.sin(v)+.2*Math.sin(u*2)]};
const transform=p=>{const a=.48+pointerX*.1,b=-.34+turn+pointerY*.07;let [x,y,z]=p;let yy=y*Math.cos(a)-z*Math.sin(a),zz=y*Math.sin(a)+z*Math.cos(a);let xx=x*Math.cos(b)+zz*Math.sin(b);zz=-x*Math.sin(b)+zz*Math.cos(b);const tilt=-.32;return [xx*Math.cos(tilt)-yy*Math.sin(tilt),xx*Math.sin(tilt)+yy*Math.cos(tilt),zz]};
const draw=()=>{ctx.clearRect(0,0,width,height);const scale=Math.min(width*.28,height*.29);ctx.save();ctx.translate(width*.53,height*.88);ctx.scale(1,.15);const shadow=ctx.createRadialGradient(0,0,0,0,0,scale*1.12);shadow.addColorStop(0,'rgba(75,65,40,.22)');shadow.addColorStop(1,'rgba(75,65,40,0)');ctx.fillStyle=shadow;ctx.beginPath();ctx.arc(0,0,scale*1.12,0,Math.PI*2);ctx.fill();ctx.restore();const faces=[],U=108,V=36;for(let i=0;i<U;i++)for(let j=0;j<V;j++){const u=i/U*Math.PI*2,v=j/V*Math.PI*2,du=Math.PI*2/U,dv=Math.PI*2/V;const pts=[point(u,v),point(u+du,v),point(u+du,v+dv),point(u,v+dv)].map(transform);const n=normal(...pts.slice(0,3));const light=Math.max(0,n[0]*-.45+n[1]*-.7+n[2]*.65);const gleam=Math.pow(Math.max(0,n[0]*-.25+n[1]*-.3+n[2]*.92),12);const rib=.94+.06*Math.cos(u*54);const shade=(.52+.43*light)*rib;const r=Math.min(255,190*shade+65*gleam),g=Math.min(255,146*shade+80*gleam),b=Math.min(255,79*shade+100*gleam);faces.push({pts,z:pts.reduce((s,p)=>s+p[2],0)/4,color:`rgb(${r|0},${g|0},${b|0})`})}faces.sort((a,b)=>a.z-b.z);for(const f of faces){ctx.beginPath();f.pts.forEach((p,i)=>{const perspective=4.8/(4.8-p[2]);const x=width*.53+p[0]*scale*perspective,y=height*.46+p[1]*scale*perspective;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.closePath();ctx.fillStyle=f.color;ctx.strokeStyle=f.color;ctx.lineWidth=.55;ctx.fill();ctx.stroke()}};
const loop=time=>{raf=0;if(!visible||document.hidden)return;if(time-last>48){if(!paused)turn+=.003;draw();last=time}if(!paused)raf=requestAnimationFrame(loop)};
const start=()=>{if(raf)cancelAnimationFrame(raf);draw();if(!paused&&visible&&!document.hidden)raf=requestAnimationFrame(loop)};
const resize=()=>{const rect=canvas.getBoundingClientRect();width=rect.width;height=rect.height;const dpr=Math.min(devicePixelRatio||1,1.8);canvas.width=width*dpr;canvas.height=height*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);start()};
new ResizeObserver(resize).observe(canvas);new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;start()}).observe(canvas);
const sync=()=>{toggle.textContent=paused?'Play motion ▷':'Pause motion Ⅱ';toggle.setAttribute('aria-pressed',String(paused));start()};toggle.onclick=()=>{paused=!paused;sync()};reduced.addEventListener('change',e=>{paused=e.matches;sync()});document.addEventListener('visibilitychange',start);canvas.addEventListener('pointermove',e=>{if(paused)return;const r=canvas.getBoundingClientRect();pointerX=(e.clientX-r.left)/r.width-.5;pointerY=(e.clientY-r.top)/r.height-.5});sync();}
